def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def as_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            a, b = x[0], x[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return int(a), int(b)
        return None

    def get_pos(obs, *keys):
        for k in keys:
            p = as_pair(obs.get(k))
            if p is not None:
                return p
        return None

    def valid_points(seq):
        out = []
        if isinstance(seq, (list, tuple)):
            for item in seq:
                p = as_pair(item)
                if p is not None:
                    out.append(p)
        return out

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = get_pos(observation, "self_position", "self_pos", "position") or (0, 0)
    ox, oy = get_pos(observation, "opponent_position", "opponent_pos", "enemy_position") or (sx, sy)
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    width = observation.get("grid_width", observation.get("width", 0))
    height = observation.get("grid_height", observation.get("height", 0))
    try:
        width = int(width)
    except Exception:
        width = 0
    try:
        height = int(height)
    except Exception:
        height = 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", observation.get("role", "pursuer"))
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = []
        if width > 0 and height > 0:
            corners = [(0, 0), (0, height - 1), (width - 1, 0), (width - 1, height - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = max(corners, key=lambda p: abs(p[0] - ox) + abs(p[1] - oy))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = valid_points(observation.get("unclaimed_cells")) or valid_points(observation.get("opponent_territory")) or valid_points(observation.get("neutral_cells"))
        if not targets:
            targets = valid_points(observation.get("frontier_cells")) or valid_points(observation.get("targets"))
        if targets:
            best = min(targets, key=lambda p: abs(p[0] - sx) + abs(p[1] - sy))
            return step_toward(self_pos, best)
        return step_away(self_pos, opp_pos)

    resources = valid_points(observation.get("resources")) or valid_points(observation.get("resource_cells")) or valid_points(observation.get("food"))
    if resources:
        best = min(resources, key=lambda p: abs(p[0] - sx) + abs(p[1] - sy))
        return step_toward(self_pos, best)

    # Default behavior: move away from opponent if threatened, otherwise stay put.
    if abs(sx - ox) + abs(sy - oy) <= 2:
        return step_away(self_pos, opp_pos)
    return [0, 0]

